// These three foreground sprites overlap the Hero and must not wait for
// lazy image intersection while their initial image height is unknown.
function loadForegroundSprites() {
  if (!desktop.matches) return;
  for (const image of scene.querySelectorAll('.mskba-v3-venues__hoop, .mskba-v3-venues__defender, .mskba-v3-venues__shooter')) {
    const full = image.dataset.mskbaLqipFullSrc;
    if (!full || image.dataset.arenaV3FullReady === '1') continue;
    image.dataset.arenaV3FullReady = '1';
    image.loading = 'eager';
    image.src = full;
  }
}
loadForegroundSprites();
desktop.addEventListener?.('change', loadForegroundSprites);
